INSERT INTO "pages" ("id", "title", "slug", "hero_eyebrow", "hero_subtitle", "hero_image_id", "content", "seo_meta_title", "seo_meta_description", "updated_at", "created_at") VALUES (7, 'Impressum', 'impressum', NULL, NULL, NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Angaben gemäß § 5 TMG","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Mozaik Bildung & Kultur e.V. Bahnhofstraße 20 65428 Rüsselsheim Vereinsregister: VR 83640 Registergericht: Darmstadt Vertreten durch:Vorsitzender: Murat Mpounartzi Stellvertretender Vorsitzende: Mustafa Uzun","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Kontakt: E-Mail:kontakt@mosaik-ruesselsheim.de","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"EU-Streitschlichtung Die Europäische Kommission stellt eine Plattform zur Online-Streitbeilegung (OS) bereit: https://ec.europa.eu/consumers/odr ; . Unsere E-Mail-Adresse finden Sie oben im Impressum.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Verbraucherstreitbeilegung/Universalschlichtungsstelle Wir sind nicht bereit oder verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Haftung für Inhalte Als Diensteanbieter sind wir gemäß § 7 Abs.1 TMG für eigene Inhalte auf diesen Seiten nach den allgemeinen Gesetzen verantwortlich. Nach §§ 8 bis 10 TMG sind wir als Diensteanbieter jedoch nicht verpflichtet, übermittelte oder gespeicherte fremde Informationen zu überwachen oder nach Umständen zu forschen, die auf eine rechtswidrige Tätigkeit hinweisen.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Verpflichtungen zur Entfernung oder Sperrung der Nutzung von Informationen nach den allgemeinen Gesetzen bleiben hiervon unberührt. Eine diesbezügliche Haftung ist jedoch erst ab dem Zeitpunkt der Kenntnis einer konkreten Rechtsverletzung möglich. Bei Bekanntwerden von entsprechenden Rechtsverletzungen werden wir diese Inhalte umgehend entfernen.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Haftung für Links","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Unser Angebot enthält Links zu externen Websites Dritter, auf deren Inhalte wir keinen Einfluss haben. Deshalb können wir für diese fremden Inhalte auch keine Gewähr übernehmen. Für die Inhalte der verlinkten Seiten ist stets der jeweilige Anbieter oder Betreiber der Seiten verantwortlich. Die verlinkten Seiten wurden zum Zeitpunkt der Verlinkung auf mögliche Rechtsverstöße überprüft. Rechtswidrige Inhalte waren zum Zeitpunkt der Verlinkung nicht erkennbar. Eine permanente inhaltliche Kontrolle der verlinkten Seiten ist jedoch ohne konkrete Anhaltspunkte einer Rechtsverletzung nicht zumutbar. Bei Bekanntwerden von Rechtsverletzungen werden wir derartige Links umgehend entfernen.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Urheberrecht Die durch die Seitenbetreiber erstellten Inhalte und Werke auf diesen Seiten unterliegen dem deutschen Urheberrecht. Die Vervielfältigung, Bearbeitung, Verbreitung und jede Art der Verwertung außerhalb der Grenzen des Urheberrechtes bedürfen der schriftlichen Zustimmung des jeweiligen Autors bzw. Erstellers. Downloads und Kopien dieser Seite sind nur für den privaten, nicht kommerziellen Gebrauch gestattet. Soweit die Inhalte auf dieser Seite nicht vom Betreiber erstellt wurden, werden die Urheberrechte Dritter beachtet. Insbesondere werden Inhalte Dritter als solche gekennzeichnet. Sollten Sie trotzdem auf eine Urheberrechtsverletzung aufmerksam werden, bitten wir um einen entsprechenden Hinweis. Bei Bekanntwerden von Rechtsverletzungen werden wir derartige Inhalte umgehend entfernen.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Quelle: e-recht24.de","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, NULL, NULL, '2026-08-28T15:23:28.345Z', '2026-08-28T13:43:56.264Z') ON CONFLICT DO NOTHING;
INSERT INTO "pages" ("id", "title", "slug", "hero_eyebrow", "hero_subtitle", "hero_image_id", "content", "seo_meta_title", "seo_meta_description", "updated_at", "created_at") VALUES (1, 'Über Uns', 'ueber-uns', 'Der Verein', 'Bildung, Dialog und Zusammenhalt in Rüsselsheim.', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Der Verein Mosaik Dialog und Kultur ist ein gemeinnütziger, eingetragener Verein in Rüsselsheim. Unser Wirkungskreis umfasst jedoch den Kreis Groß-Gerau und dem Main-Taunus-Kreis. Bildung ist unsere Priorität und wir sind fest entschlossen, die Bildung durch Sprachkurse, Nachhilfedienste, Sprachcafés usw. weiter zu fördern. Ein wichtiger Bestandteil liegt in der Förderung der Jugendarbeit. Die Jugendgruppe organisiert und betreut Aktivitäten, Reisen, Schüler- und Studentenhilfe und Sport. Wir fördern auch das kulturelle und soziale Zusammenleben, die Toleranz und den Frieden auf allen gesellschaftlichen Ebenen. Wir setzen uns für Geflüchtete und Vertriebene ein, erleichtern diesen den Einstieg in das Sozial- und Arbeitsleben. Der Verein Mosaik aus Rüsselsheim setzt sich für die Vermittlung ethischer Werte und die interkulturellen Veranstaltungen ein.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, NULL, NULL, '2026-08-28T15:23:26.309Z', '2026-08-28T13:43:54.918Z') ON CONFLICT DO NOTHING;
INSERT INTO "pages" ("id", "title", "slug", "hero_eyebrow", "hero_subtitle", "hero_image_id", "content", "seo_meta_title", "seo_meta_description", "updated_at", "created_at") VALUES (8, 'Datenschutzerklärung', 'datenschutzerklarung', NULL, NULL, NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"DATENSCHUTZERKLÄRUNG","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Datenschutz ist uns ein besonders wichtiges Anliegen, und selbstverständlich halten wir uns an die geltenden datenschutzrechtlichen Vorgaben. Wir möchten Sie daher nachfolgend über die mit dem Besuch dieser Website verbundene Verarbeitung von personenbezogenen Daten aufklären und Sie über Ihre entsprechenden Rechte informieren:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Verantwortlicher für die Datenverarbeitung:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Verantwortlicher im Sinne des Art. 4 Nr. 7 DSGVO, an den Sie sich bei Fragen oder einem anderen Anliegen zum Datenschutz wenden können, ist: Mozaik, Dialog und Kultur e.V., vertreten durch den Vorstand gem. § 26 BGB, Murat Mpounartzi, Bahnhofstraße 20, 65428 Rüsselsheim, E-Mail: mozaik.ruesselsheim@gmx.de","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Welche Daten werden erfasst und verarbeitet?","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Beim Besuch unserer Website werden auf verschiedene Weise personenbezogene Daten der Nutzer erfasst. Personenbezogene Daten sind solche Daten, mit denen eine natürliche Person identifiziert werden kann. Dazu gehören beispielsweise der Name des Betroffenen, seine Wohnadresse, seine Telefonnummer oder auch sein Geburtsdatum. Wenn Sie unsere Seite aufrufen, werden zum einen durch Ihren Browser automatisch Informationen an den Server unserer Website gesendet, sog. Zugriffsdaten bzw. Server-Logfiles, wie z.B. der verwendete Webbrowser und das verwendete Betriebssystem, der Domain-Name Ihre Internet-Providers, Ihre IP-Adresse oder auch der sog. Zeitstempel, also der genaue Zeitpunkt und die Dauer Ihres Besuchs. Diese Daten müssen notwendigerweise erfasst werden, um technisch eine Darstellung und Verbindung herzustellen. Eine Datenauswertung erfolgt jedoch nicht, auch nicht in anonymisierter Form.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Darüber hinaus erfassen wir diejenigen personenbezogenen Daten, die Sie selbst bewusst auf unserer Homepage angeben, etwa durch Nutzung unseres Kontaktformulars oder unseres Antragsformulars für eine Mitgliedschaft. Die Verwendung unseres Kontaktformulars ist nicht mit einer Speicherung personenbezogenen Daten auf unserem Server verbunden; das Formular wird als E-Mail versandt.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Zusammenfassend handelt es sich um folgende Kategorien von Daten: -Kontaktdaten (Name, Adresse, E-Mail-Adresse, Telefonnummer, etc.) -Zahlungs-bzw. Bankverbindungsdaten (nur soweit im Zusammenhang mit einem Online-Mitgliedsantrags oder bei Online Spendenabgefragt) -ggf. weitere Daten, die im Rahmen einer Online-Antragstellung abgefragt werden -inhaltliche Daten (eingestellte Texte und übersandte Nachrichten, eingestellte Fotos, ggf. Videos) -Kommunikationsdaten (Geräte-Informationen, IP-Adresse) -Nutzungsdaten (besuchte Website, Nutzungsdauer etc.)","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Rechtsgrundlage für die Verarbeitung:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Als maßgebliche Rechtsgrundlagen für die Zulässigkeit der Verarbeitung dienen die EU-Datenschutzgrundverordnung vom 27.04.2016 sowie das Bundesdatenschutzgesetz i.d.F. v. 30.06.2017. Die Rechtmäßigkeit der Datenerfassung ergibt sich aus Art. 6 DSGVO. Soweit die Datenverarbeitung aufgrund einer ausdrücklichen Einwilligung erfolgt, dient Abs. 1 a) der genannten Norm als Rechtsgrundlage. Für die Speicherung und sonstige Verarbeitung Ihrer Daten im Zusammenhang mit der Verwendung unseres Online-Mitgliedsantrages ist das mitgliedschaftliche Vertragsverhältnis zwischen Ihnen und dem Verein in Verbindung mit Art. 6 Abs. 1 b) DSGVO Rechtsgrundlage. Das gilt auch für alle anderen Datenverarbeitungen, die zur Durchführung vertraglicher Maßnahmen, aber auch zur Beantwortung von Anfragen erforderlich sind. Soweit wir im Einzelfall zur Datenverarbeitung rechtlich verpflichtet sind, ist hierfür Art. 6 Abs. 1 c) DSGVO Grundlage; im dem Fall, dass die Verarbeitung der Wahrung unserer berechtigten Interessen dient, Art. 6 Abs. 1 f) DSGVO.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Zweck und Dauer der Datenverarbeitung:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Die automatische Erfassung Ihrer Nutzer- und Kommunikationsdaten beim Besuch unserer Website dient notwendigerweise der Herstellung der technischen Verbindung und Nutzbarkeit unserer Website. Soweit Sie das auf unserer Homepage enthaltene Kontaktformular verwenden oder Sie uns über die Seite eine E-Mail schicken, dient die Erfassung der in diesem Zusammenhang bekannt gegebenen Kontaktdaten (in der Regel nur Name und E-Mail-Adresse) lediglich der entsprechenden Rückmeldung unsererseits. Eventuelle zusätzliche Angaben, die Sie uns übermitteln, werden allein dem Zweck und Anlass entsprechend verarbeitet. Nach Wegfall des Grundes für die Speicherung, werden die Daten unverzüglich gelöscht oder –sofern im Einzelfall erforderlich –gesperrt. Wenn Sie unser Online-Formular für einen Antrag auf Vereinsmitgliedschaft nutzen, werden Ihre dort gemachten Angaben allein zur Begründung und Durchführung des mitgliedschaftlichen Vertragsverhältnisses verwendet. Diese Daten werden lediglich für die Dauer der Vereinsmitgliedschaft im Rahmen unserer Mitgliederverwaltung gespeichert und ausschließlich hierfür genutzt. Nach Beendigung der Mitgliedschaft werden die Daten gelöscht oder –soweit notwendig –gesperrt.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Weitergabe von personenbezogenen Daten:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Die von Ihnen übermittelten personenbezogenen Daten werden nicht an Dritte weitergegeben, weder zu kommerziellen noch zu nichtkommerziellen Zwecken.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Datensicherheit:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Wir versichern, dass wir die nach Art. 32 DSGVO erforderlichen technischen sowie organisatorischen Maßnahmen ergriffen haben, um ein dem Risiko für die Rechte und Freiheiten des Nutzers angemessenes Schutzniveau zu gewährleisten. Dies betrifft insbesondere die Auswahl der verwendeten Hard- und Software sowie die innerorganisatorische Kontrolle und Zugriffsberechtigung. Nichtsdestotrotz wird vorsorglich darauf hingewiesen, dass die Datenübertragung im Internet (z.B. per E-Mail) immer gewisse Sicherheitslücken aufweisen und nicht vollumfänglich vor dem Zugriff durch Dritte geschützt werden kann.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Rechte des Betroffenen:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Sie haben hinsichtlich der Verarbeitung Ihrer personenbezogenen Daten nach den geltenden datenschutzrechtlichen Bestimmungen insbesondere einen Anspruch auf","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"-Information und Auskunft über die von uns vorgenommene Verarbeitung Ihrer personenbezogenen Daten (Art. 15 DSGVO),","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"-auf Berichtigung und Vervollständigung bezüglich unrichtiger bzw. unvollständiger Daten (Art. 16 DSGVO) und","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"-auf Löschung nach Maßgabe des Art. 17 DSGVO bzw. auf Einschränkung nach Art. 18 DSGVO.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Widerspruch und Widerruf von Einwilligungen:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Soweit Ihre personenbezogenen Daten im Rahmen des Art. 6 Abs. 1 f) DSGVO erhoben und verarbeitet werden (d.h. bei Vorliegen berechtigter Interessen des Verantwortlichen), haben Sie nach Art. 21 DSGVO das Recht, hiergegen jederzeit Widerspruch einzulegen, wenn insoweit Gründe bestehen, die sich aus Ihrer besonderen Situation ergeben, oder wenn sich der Widerspruch gegen eine Direktwerbung richtet. Soweit eine Datenverarbeitung aufgrund Ihrer diesbezüglichen vorherigen Einwilligung erfolgt ist, steht es Ihnen jederzeit frei, Ihre Einwilligung in den betreffenden Datenverarbeitungsvorgang zu widerrufen. Sowohl für den Widerspruch als auch für den Widerruf genügt eine einfache Mitteilung per E-Mail an uns. Die betreffenden personenbezogenen Daten werden dann unverzüglich gelöscht.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Beschwerderecht:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Nach Art. 77 DSGVO hat ein Betroffener im Falle eines datenschutzrechtlichen Verstoßes das Recht, sich mit einer entsprechenden Beschwerde an die zuständige Aufsichtsbehörde zu wenden. Hierbei handelt es sich um den Datenschutzbeauftragten des Landes Hessen, Der Hessische Beauftragte für Datenschutz und Informationsfreiheit Prof. Dr. Alexander Roßnagel, Gustav-Stresemann-Ring 1, 65189 Wiesbaden.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Verschlüsselung:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Aus Sicherheitsgründen nutzen wir auf unserer Seite eine SSL-bzw. TLS-Verschlüsselung, was Sie an dem Schloss-Symbol in der Browserzeile sowie an der Abkürzung „https://“ (statt „http://“) erkennen können. Ist die Verschlüsselung aktiv, können Daten bzw. inhaltliche Angaben, die Sie an uns übermitteln, von Dritten nicht mitgelesen werden.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Cookies:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Um die Nutzung bestimmter Funktionen auf unserer Webseite zu ermöglichen, verwenden wir sog. Cookies. Hierbei handelt es sich um kleine Textdateien, die auf Ihrem Rechner abgelegt werden, um Sie bei Ihrem nächsten Besuch auf unserer Internetseite wiederzuerkennen. Sie ersparen Ihnen dann z.B. die wiederholte Eingabe von Daten und erleichtern zugleich die Übermittlung bestimmter Inhalte der Webseite. Cookies richten auf Ihrem Computer keinen Schaden an und enthalten auch keine Computerviren.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Selbstverständlich können Sie den Einsatz dieser Cookies verweigern; insoweit bitten wir Sie, die Cookies bei den Sicherheitseinstellungen Ihres Browsers zu deaktivieren. Auch ist es möglich, Cookies –soweit sie nach Beendigung Ihres Besuches auf unserer Homepage ohnehin nicht automatisch gelöscht werden –im Nachgang zu löschen. Wir weisen allerdings darauf hin, dass die Nichtaktivierung von Cookies zu Einschränkungen bei den betreffenden Funktionen führen kann.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, NULL, NULL, '2026-08-28T15:23:28.670Z', '2026-08-28T13:43:56.574Z') ON CONFLICT DO NOTHING;

-- Data for "projects" (17 rows)
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (3, 'Internationaler Frauentag: Wir feiern die Kraft und die Arbeit der Frauen', 'internationaler-frauentag-wir-feiern-die-kraft-und-die-arbeit-der-frauen', NULL, 'Jedes Jahr am 8. März wird weltweit der Internationale Frauentag gefeiert, ein besonderer Tag, der den Beitrag der Frauen zur Gesellschaft würdigt und ihren Kampf für ihre Rechte ehrt. Die Ursprünge dieses Tages reichen ', 11, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Jedes Jahr am 8. März wird weltweit der Internationale Frauentag gefeiert, ein besonderer Tag, der den Beitrag der Frauen zur Gesellschaft würdigt und ihren Kampf für ihre Rechte ehrt. Die Ursprünge dieses Tages reichen bis in die frühen 1900er Jahre zurück, als Arbeiterinnen für bessere Arbeitsbedingungen und das Wahlrecht kämpften. Heute ist dieser Tag zu einem wichtigen Symbol für das Bewusstsein für Frauenrechte und die Förderung der Gleichstellung geworden.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"tag":"h2","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Der Beitrag von Frauen zur Gesellschaft","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Frauen spielen in allen Lebensbereichen eine große Rolle – von der Familie über die Wirtschaft bis hin zur Wissenschaft und Kunst. Besonders in den letzten Jahren haben Frauen vermehrt Positionen in der Arbeitswelt, der Politik und der Wissenschaft eingenommen, was zur gesellschaftlichen Entwicklung und Innovation weltweit beigetragen hat. Dennoch gibt es immer noch viele Herausforderungen auf dem Weg zur vollständigen Gleichstellung.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"tag":"h2","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Frauenrechte und Gleichberechtigung","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Es ist von entscheidender Bedeutung, das Bewusstsein für Frauenrechte zu stärken und unterstützende Maßnahmen zu ergreifen, damit Frauen die ihnen zustehende Gleichstellung erreichen. Themen wie gleiche Bezahlung, Zugang zu Bildung und ein Leben ohne Gewalt sind nach wie vor weltweit aktuelle Diskussionsthemen, die verbessert werden müssen.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"tag":"h2","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Was können wir am Internationalen Frauentag tun?","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Der Internationale Frauentag ist nicht nur ein Tag zum Feiern, sondern auch eine Gelegenheit, sich über Frauenrechte zu informieren und Unterstützung zu leisten. Heute können wir die Erfolge von Frauen anerkennen, uns an unterstützenden Projekten beteiligen und gesellschaftliches Bewusstsein schaffen.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Anlässlich dieses besonderen Tages, an dem wir die Kraft und die Arbeit der Frauen würdigen, wünschen wir allen Frauen einen glücklichen Internationalen Frauentag!","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '1', '2026-08-28T15:29:14.227Z', '2026-08-28T15:23:30.115Z', '2025-03-08T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (5, 'Mosaik e.V. Rüsselsheim wünscht euch Ein Neues Jahr 2025', 'mosaik-e-v-ruesselsheim-wuenscht-euch-ein-neues-jahr-2025', NULL, 'Mosaik e.V. Rüsselsheim wünscht euch besinnliche weihnachten und Ein Neues Jahr voller kultureller entdeckungen, lehrreicher bildung und Inspirierendem Dialog.', 13, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Mosaik e.V. Rüsselsheim wünscht euch besinnliche weihnachten und Ein Neues Jahr voller kultureller entdeckungen, lehrreicher bildung und Inspirierendem Dialog.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"2025 steht vor der Tür – möge es ein Jahr voller Lachen, Liebe und Lichtblicke für dich werden. Wir wünschen ihnen eine Reise voller neuer Entdeckungen, Freude und unvergesslicher Momente. Ein gesundes und Frohes neues Jahr!","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '3', '2026-08-28T15:29:16.086Z', '2026-08-28T15:23:30.801Z', '2025-01-01T00:00:00.000Z') ON CONFLICT DO NOTHING;
