INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (7, 'Weltwandertag', 'weltwandertag', NULL, NULL, 15, NULL, '5', '2026-08-28T15:29:17.423Z', '2026-08-28T15:23:31.291Z', '2024-12-25T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (9, 'Gemeinsam mit Pfarrern Prawitz & Jung am Ashura Tag', 'gemeinsam-mit-pfarrern-prawitz-and-jung-am-ashura-tag', NULL, 'Am 22.8.2021 hatten wir anlässlich des Ashura Tages die Ehre Herr Pfarrer Prawitz vom Pfarramt für Ökumene im evangelischen Dekanat Groß-Gerau und Herrn Pfarrer Andreas Jung von der evangelischen Martinsgemeinde in Rüsse', 17, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Am 22.8.2021 hatten wir anlässlich des Ashura Tages die Ehre Herr Pfarrer Prawitz vom Pfarramt für Ökumene im evangelischen Dekanat Groß-Gerau und Herrn Pfarrer Andreas Jung von der evangelischen Martinsgemeinde in Rüsselsheim in unseren Vereinsräumlichkeiten zu empfangen und gemeinsam zu Mittag zu essen. Anschließend haben wir Ashura verzehrt und über die Bedeutung des Ashura Tages gesprochen.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '7', '2026-08-28T15:29:18.810Z', '2026-08-28T15:23:32.332Z', '2024-12-15T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (11, 'Jugendplattform kam es zu einem Zusammenkommen mit Jugendlichen', 'jugendplattform-kam-es-zu-einem-zusammenkommen-mit-jugendlichen', NULL, 'Im Rahmen des “ Jugendtreffen ” Programms der Rüsselsheim Mosaik Dialog & Kultur e.V. Jugendplattform kam es zu einem Zusammenkommen mit Jugendlichen.', 19, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Im Rahmen des “ Jugendtreffen ” Programms der Rüsselsheim Mosaik Dialog & Kultur e.V. Jugendplattform kam es zu einem Zusammenkommen mit Jugendlichen.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Im Rahmen des Programms trafen sich Gruppen von Jugendlichen mit somalischen, syrischen, afghanischen und türkischen Wurzeln. Nach einem traditionellen Maklube-Essen gab es türkischen Baklava und Tee, bei dem sie in einer warmen Atmosphäre zusammenkamen und sich unterhielten.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Der stellvertretende Vorsitzende des Vereins, Mustafa Uzun, betonte in seiner Rede im Rahmen des Programms, dass der Verein glücklich sei, eine Umgebung zu schaffen, in der die Jugendlichen untereinander Erfahrungen austauschen können.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Die Sitzung, bei der hauptsächlich Themen wie das deutsche Bildungssystem, Ausbildungsalternativen und die Bedeutung der Sprache im Integrationsprozess behandelt wurden, endete mit dem Beschluss, dass in den kommenden Monaten verschiedene Themen behandelt werden könnten.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '9', '2026-08-28T15:29:20.365Z', '2026-08-28T15:23:32.737Z', '2024-12-14T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (12, 'Willkommen im neuen Schuljahr', 'willkommen-im-neuen-schuljahr', NULL, 'Mitglieder und Freiwillige des “Rüsselsheim Mosaik Vereins” trafen sich an einem speziellen Spielraum im Rahmen der Veranstaltung “Willkommen im neuen Schuljahr” für Kinder, die dieses Jahr zum ersten Mal zur Schule gehe', 20, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Mitglieder und Freiwillige des “Rüsselsheim Mosaik Vereins” trafen sich an einem speziellen Spielraum im Rahmen der Veranstaltung “Willkommen im neuen Schuljahr” für Kinder, die dieses Jahr zum ersten Mal zur Schule gehen werden.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Der stellvertretende Vorsitzende des Vereins, Mustafa Uzun, teilte seine Gefühle mit und sagte: “Wir wollten diesen wichtigen Schritt für jedes Kind und jede Familie gemeinsam feiern, es war ein tolles Programm.”","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Außerdem wurde im Rahmen des Programms eine Umgebung geschaffen, in der die Kinder ein paar ihrer Lieblingsspielzeuge mitbringen und gegen ein anderes Spielzeug tauschen konnten, um das Verständnis fürs Teilen zu fördern und eine andere Art des Miteinanders zu erleben.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Das Programm, bei dem die Kinder mit kleinen Geschenken erfreut wurden, endete mit Snacks wie Obst.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '10', '2026-08-28T15:29:21.005Z', '2026-08-28T15:23:33.009Z', '2024-12-14T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (13, 'Jugend trifft sich', 'jugend-trifft-sich', NULL, 'Im Sommer 2022 haben mehr als 80 Kinder und Jugendliche an unseren herausragenden Aktivitäten im Rahmen des Projekts AUF!leben teilgenommen. Etwa die Hälfte von ihnen waren Mädchen und viele von ihnen gehörten der Risiko', 21, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Im Sommer 2022 haben mehr als 80 Kinder und Jugendliche an unseren herausragenden Aktivitäten im Rahmen des Projekts AUF!leben teilgenommen. Etwa die Hälfte von ihnen waren Mädchen und viele von ihnen gehörten der Risikolage an.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Das Projekt wurde organisiert, um die negativen Auswirkungen der Corona-Pandemie auf Kinder und Jugendliche zu überwinden. Dabei gab es 3 folgende Prioritäten:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"– Förderung der psychischen Gesundheit von Kindern und Jugendlichen","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"– Unterstützung des sozial-emotionalen Lernens sowie der Beziehungen und Bindungen von Kindern und Jugendlichen","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"– Begleitung von Kindern und Jugendlichen bei der Wiederaneignung verlorengegangener Alltagsstrukturen und -erfahrungen","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Das Projekt griff Aktivitäten aus dem Alltag der Teilnehmenden auf und beinhaltete gemeinsame Aktivitäten für Teilnehmende aus benachteiligten und nicht benachteiligten Verhältnissen (z. B. unterschiedliche Bildungshintergründe). Es enthielt auch Freiräume, in denen die Teilnehmer selbst entscheiden konnten, wie eine Aktivität organisiert werden sollte (z. B. wohin sie gehen, welche Aktivität sie wählen, wie sie die Teams aufteilen). Das Projekt griff die Interessen und Bedürfnisse der Teilnehmenden (z. B. Hobbys, Bildungsdefizite) sowie die vorhandenen Stärken der Teilnehmenden (z. B. Persönlichkeit, Fähigkeiten) auf.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Zu den üblichen Treffen gehörten:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"– eine Unterhaltungs-, Sport- oder Spaßaktivität, wie z. B. LaserTag, Trampolin, Bowling, Kletterpark, eine Bootsfahrt, Escape Room, Colgone View, Seilbahn, Tiggolino Kinderspielparadis, Jump n Fly, Bogenschießen, Schwimmbad und/oder","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"– Orts- und/oder Stadtbesuche wie Kinobesuche, Besuche der Rüdesheimer Seilbahn, Picknick und Grill in Parks, und Stadtrundfahrten nach Frankfurt, Wiesbaden, Mainz, Köln und Bingen, Taunus Wunderland","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"– ein Workshop mit Medien, Lehrvideos, Kurzgeschichten, Büchern, Brainstorming und Diskussionsgruppen. Themen waren unter anderem Zeitmanagement (Zeitaufwand für elektronische Geräte), Planung (wöchentlich, monatlich, jährlich), Lesegewohnheit, Vorteile einer Bibliothek, Vertrauen, Umweltbewusstsein (Main Clean Up), Respekt (z. B. gegenüber benachteiligten Personen, Eltern, Älteste, Umwelt), Toleranz (z. B. gegenüber anderen Ideen, Weltanschauungen, Kulturen) und Rassismus. Wir glauben, dass diese Themen besonders wichtig sind, um die negativen Auswirkungen der Corona-Pandemie auf die Jugend zu überwinden.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"– gemeinsames Essen","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Bei der Auswahl einer Sport-, Spaß- oder Unterhaltungsaktivität oder eines Besuchsortes wurden Altersgruppen, Vorlieben und Hobbys der Jugendlichen, Anzahl der Teilnehmer, Verfügbarkeit eines bestimmten Ortes, finanzielle Möglichkeiten, Teilnahmequoten und andere berücksichtigt.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '11', '2026-08-28T15:29:22.140Z', '2026-08-28T15:23:33.269Z', '2024-12-14T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (16, 'Spenden Aktion Ukraine', 'spenden-aktion-ukraine', NULL, 'Mit großer Freude freuen sich die Mitglieder von Mozaik e.V. nahm an der “Spenden Aktion Ukraine” teil.Mehrere verschiedene selbstgebackene köstliche Kuchen, Süßigkeiten und Backwaren wurden von großzügigen Familien zube', 23, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Mit großer Freude freuen sich die Mitglieder von Mozaik e.V. nahm an der “Spenden Aktion Ukraine” teil.Mehrere verschiedene selbstgebackene köstliche Kuchen, Süßigkeiten und Backwaren wurden von großzügigen Familien zubereitet.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Die Spende war eine Nachbarschaftsinitiative, die auf dem Opelplatz in Rüsselsheim 60 Kuchenspenden verkaufte, um Bedürftigen in der Ukraine zu helfen. Insgesamt kamen über 2400€ für die Spende zusammen.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '14', '2026-08-28T17:45:09.706Z', '2026-08-28T15:23:33.980Z', '2022-04-25T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (17, 'in den Überflutungsgebieten eine Säuberungsaktion', 'in-den-ueberflutungsgebieten-eine-saeuberungsaktion', NULL, 'Die Folgen der Hochwasser-Katastrophe in Deutschland sind verheerend. Das Ausmaß der Zerstörungen hat eine noch nie dagewesene Dimension erreicht. Es sind nicht nur Straßen weggerissen oder Häuser eingestürzt, die Flut h', 24, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Die Folgen der Hochwasser-Katastrophe in Deutschland sind verheerend. Das Ausmaß der Zerstörungen hat eine noch nie dagewesene Dimension erreicht. Es sind nicht nur Straßen weggerissen oder Häuser eingestürzt, die Flut hat dutzende Vermisste und Tote verursacht. Unser Mitgefühl gilt den Angehörigen der Toten, denen wir unser tief empfundenes Beileid aussprechen. Auch die Mosaik Dialog & Kultur e.V. versucht in dieser Krisensituation da zu unterstützen, wo es nur geht. Denn zahlreiche Flüchtlinge haben am eigenen Leib gespürt, was es bedeutet, alles zu verlieren und von Null anzufangen. Das Credo lautet daher: “Deutschland hat uns aufgenommen und uns eine Heimat gegeben. Jetzt möchten wir unserer neuen Heimat beim Wiederaufbau helfen“.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Mit diesen Gedanken haben die Flüchtlingsmitglieder der Initiative, Wir als Mozaik Dialog & Kultur e.V. in Rüsselsheim fahren am Samstag, 24.07.2021, nach Koblenz-Sinzig, um dort die Menschen aus dem Katastrophengebiet zu versorgen und ihnen zu helfen. 4 ehrenamtliche Gruppen mit insgesamt 19 Mitgliedern des Vereins und Flüchtlingen aus der Türkei werden sich auf den Weg machen. Arbeitskleidung, Stiefel, Essen und Getränke wurden für die Menschen vorbereitet. Auch am Sonntag, 25.07.2021, werden drei ehrenamtliche Gruppen des Vereins mit insgesamt 14 Personen in dieselbe Region fahren, um zu arbeiten und den Menschen vor Ort zu helfen. Essen für 250 Personen wurde auch zubereitet.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Wir danken herzlich allen ehrenamtlichen Helfern des Vereins und Time to Help e.V. für die Zusammenarbeit.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '15', '2026-08-28T17:45:10.750Z', '2026-08-28T15:23:34.561Z', '2021-07-25T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (18, 'Fahrradtour am Weltflüchtlingstag', 'fahrradtour-am-weltfluechtlingstag', NULL, 'Als Mosaik Dialog Kultur e.V. Rüsselsheim haben wir zusammen mit Mosaik e.V Wiesbaden am 20. Juni 2021 anlässlich des Weltflüchtlingstages eine Fahrradtour (ca. 10 km) vom Startpunkt Oestrich-Winkel mit einer Abschlussku', 25, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Als Mosaik Dialog Kultur e.V. Rüsselsheim haben wir zusammen mit Mosaik e.V Wiesbaden am 20. Juni 2021 anlässlich des Weltflüchtlingstages eine Fahrradtour (ca. 10 km) vom Startpunkt Oestrich-Winkel mit einer Abschlusskundgebung in Rüdesheim durchgeführt. An der Fahrradtour nahmen etwa 80 Radfahrer unterschiedlicher Altersgruppen teil. Die Veranstaltung hatte das Ziel, daran zu erinnern, was es heißt ein Flüchtling zu sein. Anhand von Plakaten wurden auch einige Daten über die politische Verfolgung in der Türkei zum Ausdruck gebracht.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '16', '2026-08-28T17:45:11.673Z', '2026-08-28T15:23:35.228Z', '2021-07-25T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (14, 'Bereit für Spaß und Lernen?', 'bereit-fuer-spass-und-lernen', NULL, '“Die zweiwöchige Sommerkurs-Veranstaltung des Rüsselsheim Mosaik Vereins unter dem Motto ‘Bereit für Spaß und Lernen?’ fand ihren Abschluss mit einem Besuch im Experiminta Science Museum in Frankfurt.', 26, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"“Die zweiwöchige Sommerkurs-Veranstaltung des Rüsselsheim Mosaik Vereins unter dem Motto ‘Bereit für Spaß und Lernen?’ fand ihren Abschluss mit einem Besuch im Experiminta Science Museum in Frankfurt.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Während der Veranstaltung tauchten die Teilnehmer in eine Welt von Denk- und Intelligenzspielen ein. Besonders beliebt waren Aktivitäten wie das Lesen von Büchern und das Abschließen von Geschichten. Um das Bewusstsein für gesundes Leben zu fördern, wurden während der Veranstaltung Snacks angeboten, vor allem Früchte.”","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '12', '2026-08-28T17:45:13.227Z', '2026-08-28T15:23:33.487Z', '2023-08-25T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (2, 'Rührender Besuch zum Muttertag in Seniorenheimen', 'ruehrender-besuch-zum-muttertag-in-seniorenheimen', NULL, 'Anlässlich des Muttertags organisierte der Verein Mosaik Dialog e.V. Rüsselsheim in Zusammenarbeit mit den Seniorenheimen Senterra Am Friedensplatz und DOREAFAMILIE Flörsheim Eduard Schwerzel ein besonderes Besuchsprogra', 10, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Anlässlich des Muttertags organisierte der Verein Mosaik Dialog e.V. Rüsselsheim in Zusammenarbeit mit den Seniorenheimen Senterra Am Friedensplatz und DOREAFAMILIE Flörsheim Eduard Schwerzel ein besonderes Besuchsprogramm.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Unter dem Motto „Ich gehe zu meiner Oma“ wurden an die Bewohnerinnen und Bewohner sowie das Pflegepersonal liebevoll gestaltete Muttertagskarten, Rosen und kleine Geschenke überreicht.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Jugendliche aus den Familien der Vereinsmitglieder erfreuten die Seniorinnen und Senioren zudem mit einem kleinen Geigenkonzert, das für emotionale Momente sorgte. Am Ende der Veranstaltung bedankte sich Frau Wunderlich, die Sozialverantwortliche des Seniorenheims, herzlich bei den Besuchern und den freiwilligen Helfern des Vereins für ihr Engagement.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Mustafa Uzun, der stellvertretende Vorsitzende des Mosaik Dialog Vereins, äußerte seinen Wunsch nach einer friedlichen Welt, in der Menschen in Brüderlichkeit ihre Mütter und Liebsten umarmen können.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"„Heute haben wir die Geschenke, die wir vielleicht unseren eigenen Müttern oder die Kinder ihren Großeltern nicht persönlich geben konnten, symbolisch den älteren Menschen hier überreicht. Dabei konnten unsere Kinder und wir gemeinsam ein Bild voller Liebe und Mitgefühl erleben. Wir hoffen, dass sich diese Wärme auf die ganze Welt überträgt“, sagte Uzun.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '0', '2026-08-28T15:29:13.323Z', '2026-08-28T15:23:29.834Z', '2025-05-11T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (4, 'Iftar Abend', 'iftar-abend', NULL, 'Sehr geehrte Damen und Herren,', 12, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Sehr geehrte Damen und Herren,","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"der Fastenmonat Ramadan ist für Musliminnenweltweit eine besondere Zeit der Besinnung. Von derMorgendämmerung (ca. 04:32 Uhr) bis zumSonnenuntergang (ca. 18:45 Uhr) verzichten sietägsüber auf Essen und Trinken. Am Abend wird dasFastenbrechen (Iftar) in gemeinschaftlich gefeiert. Wir, Mosaik Dialog & Kultur e.V., laden Sie herzlichzu unserem Iftar-Abend am 23. März ein. Gemeinsammöchten wir diese besondere Tradition erleben undden Abend bei einem gemeinsamen Essen ausklingenlassen. Wir freuen uns auf Ihr Kommen.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Sonntag, 23.03.2025 | 18:00 - 20:30 Uhr","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '2', '2026-08-28T15:29:15.263Z', '2026-08-28T15:23:30.499Z', '2025-03-08T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (8, 'Alles liebe zum Muttertag', 'alles-liebe-zum-muttertag', NULL, 'Der Verein „Mosaik Dialog“ im hessischen Bundesland hat zum Muttertag (08.Mai 2022) ein Programm im Seniorenheim „Senterra care Residenz Ruesselsheim“ organisiert. Mit dem Slogan „Neneme gidiyorum, Dedeme gidiyorum“ wurd', 16, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Der Verein „Mosaik Dialog“ im hessischen Bundesland hat zum Muttertag (08.Mai 2022) ein Programm im Seniorenheim „Senterra care Residenz Ruesselsheim“ organisiert. Mit dem Slogan „Neneme gidiyorum, Dedeme gidiyorum“ wurde gestartet und den Bewohnern und Mitarbeitern im Seniorenheim Rosen und Geschenke mit Postkarten geschenkt. Ein junger Vereinsmitglied hat zum Anlass des Tages ein Minikonzert mit seiner Geige vorgeführt. Nach diesen emotionalen Momenten hat sich die Sozialarbeiterin des Hauses Frau Yagop bei den Besuchern und den ehrenamtlichen Vereinsmitgliedern herzlich bedankt.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Der zweite Vereinsvorsitzender Mustafa Uzun betonte nochmals, dass sie in der Ukraine und auch überall auf eine Welt ohne Krieg, mit viel Liebe und Gemeinsamkeiten hoffen. Zum Abschluss sprach Uzun: „Heute haben unsere Kinder die Geschenke, die sie eigentlich ihren eigenen Großeltern schenken wollten, aber leider nicht konnten, hier den Mitbewohnern ihres Hauses geschenkt und sich trotzdem ein wenig gefreut. Zum Anlass des Tages haben wir und unsere Kinder schöne, liebevolle und fürsorgliche Momente erleben können. Wir wünschen, dass diese Schönheit sich überall auf der ganzen Welt widerspiegelt.“","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '6', '2026-08-28T15:29:18.143Z', '2026-08-28T15:23:31.873Z', '2024-12-15T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (10, 'Mosaik Dialog & Kultur e.V. versammelte die Kinder zu einer ‘Tag der Güte’ Veranstaltung', 'mosaik-dialog-and-kultur-e-v-versammelte-die-kinder-zu-einer-tag-der-guete-veranstaltung', NULL, 'Der Rüsselsheim Mosaik Dialog & Kultur Verein versammelte am Freitag, den 12. Januar, die Kinder und Familien seiner Mitglieder und Freiwilligen zu einer ‘Tag der Güte’ Veranstaltung.', 18, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Der Rüsselsheim Mosaik Dialog & Kultur Verein versammelte am Freitag, den 12. Januar, die Kinder und Familien seiner Mitglieder und Freiwilligen zu einer ‘Tag der Güte’ Veranstaltung.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Der “Tag der Güte” war so geplant, dass jedes teilnehmende Kind einige nicht mehr benutzte Spielzeuge von zu Hause mitbrachte und im Austausch dafür ein Spielzeug aussuchen konnte, das es mochte.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Das Programm bestand nicht nur aus Spielzeugen und Kindern. Die teilnehmenden Familien teilten und boten auch die zu Hause zubereiteten Speisen miteinander an. Auf diese Weise setzten sowohl die Kleinen als auch die Erwachsenen ein schönes Beispiel für die Kultur des Teilens um.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Im Kontext der Veranstaltung teilte Mustafa Uzun, der stellvertretende Vorsitzende des Vereins, seine Gedanken wie folgt mit: “Der zentrale Zweck dieser Initiative lag darin, insbesondere bei unseren jüngsten Teilnehmern das Bewusstsein für das Teilen zu wecken und zu fördern. Wir wollten erlebbar machen, dass dieses wertvolle Gefühl des Teilens in jedem Lebensalter eine Rolle spielen kann. Wie das bekannte Sprichwort besagt: ‘Teilen ist eine Freude’.”","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '8', '2026-08-28T15:29:19.467Z', '2026-08-28T15:23:32.534Z', '2024-12-14T00:00:00.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "projects" ("id", "title", "slug", "partner", "excerpt", "cover_image_id", "content", "order", "updated_at", "created_at", "published_date") VALUES (15, 'Müllsammelaktion am Weltumwelttag', 'muellsammelaktion-am-weltumwelttag', NULL, 'Am Weltumwelttag, 05. Juni 2022, haben wir als Mozaik e.V. im Rüsselsheim Ostpark und Umgebung effektiv Müll eingesammelt und gesäubert.', 22, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Am Weltumwelttag, 05. Juni 2022, haben wir als Mozaik e.V. im Rüsselsheim Ostpark und Umgebung effektiv Müll eingesammelt und gesäubert.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Freiwillige des Vereins und ihre Familien trafen sich im Rüsselsheim Ost Park und führten die Reinigungsprozedur für 2 Stunden durch. Unser Motto war „Die Umwelt gehört uns, wir sind die Umwelt“ .","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"2. Vorsitzender, Mustafa Uzun, sagte: „Solche Tage und Aktivitäten sind besonders wichtig, um das Bewusstsein für unsere Umwelt zu schärfen. Die Mehrheit der Vereinsmitglieder sind Neubürger in Deutschland. Als Teil dieses Landes freuen wir uns, heute hier zu sein. Auch unsere Kinder nahmen sehr gerne freiwillig an dieser Aktivität teil, was uns ebenfalls sehr gefreut hat.Die Welt gehört jedem von uns, diejenigen vor uns haben sich bemüht, die Welt zu einem besseren Ort zu machen. Wir müssen uns auch bemühen, es zu einem viel besseren Ort mit einer besseren Umgebung zu machen.”","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr"}}'::jsonb, '13', '2026-08-28T17:45:08.719Z', '2026-08-28T15:23:33.750Z', '2022-06-09T00:00:00.000Z') ON CONFLICT DO NOTHING;

