-- Data for "homepage" (1 rows)
INSERT INTO "homepage" ("id", "hero_eyebrow", "hero_title", "hero_subtitle", "intro_title", "intro_text", "cta_title", "cta_text", "updated_at", "created_at") VALUES (1, 'Gemeinsam für Bildung, Toleranz und Frieden', 'Mosaik Dialog und Kultur e.V.', 'Der gemeinnützige Verein in Rüsselsheim – Bildung, Jugendarbeit und interkultureller Dialog, im Kreis Groß-Gerau und im Main-Taunus-Kreis.', 'Über Uns', 'Der Verein Mosaik Dialog und Kultur ist ein gemeinnütziger, eingetragener Verein in Rüsselsheim. Unser Wirkungskreis umfasst jedoch den Kreis Groß-Gerau und dem Main-Taunus-Kreis. Bildung ist unsere Priorität und wir sind fest entschlossen, die Bildung durch Sprachkurse, Nachhilfedienste, Sprachcafés usw. weiter zu fördern.', 'Ihre Unterstützung macht einen Unterschied!', 'Jede Spende hilft uns dabei, unsere Programme fortzuführen und noch mehr Menschen in unserer Gemeinschaft zu unterstützen.', '2026-08-28T15:23:36.597Z', '2026-08-28T13:43:53.916Z') ON CONFLICT DO NOTHING;

