-- Data for "donation" (1 rows)
INSERT INTO "donation" ("id", "hero_title", "hero_subtitle", "hero_text", "paypal_url", "bank_account_holder", "bank_iban", "bank_bic", "bank_bank_name", "bank_purpose", "cta_title", "cta_text", "updated_at", "created_at") VALUES (1, 'Mosaik Dialog und Kultur', 'Gemeinsam für Bildung, Toleranz und Frieden', 'Mosaik Dialog und Kultur ist ein eingetragener gemeinnütziger Verein in Rüsselsheim. Wir konzentrieren uns auf Bildung, Jugendprogramme, kulturelles Zusammenleben und Flüchtlingsunterstützung.', NULL, 'MOZAIK DIALOG UND KULTUR E.V.', 'DE10 5085 2553 0016 0896 58', 'HELADEF1GRG', 'Kreissparkasse Groß-Gerau', 'Spende', 'Ihre Unterstützung macht einen Unterschied!', 'Jede Spende hilft uns dabei, unsere Programme fortzuführen und noch mehr Menschen in unserer Gemeinschaft zu unterstützen.', '2026-08-28T15:23:37.255Z', '2026-08-28T13:43:54.361Z') ON CONFLICT DO NOTHING;

